import { useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxStepper } from '@jinx-ui/react';

export type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const COUNTRIES = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const EMPTY: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);
  const [touched, setTouched] = useState(false);

  const set = <K extends keyof RegistrationValues>(key: K, value: RegistrationValues[K]) => {
    setValues((prev) => ({ ...prev, [key]: value }));
  };

  const errors = {
    name: values.name.trim() ? undefined : 'Укажите имя',
    email: values.email.includes('@') ? undefined : 'Укажите адрес с символом @',
    phone: values.phone.trim().length >= 10 ? undefined : 'Укажите номер полностью',
    country: values.country ? undefined : 'Выберите страну',
    city: values.city.trim() ? undefined : 'Укажите город',
    street: values.street.trim() ? undefined : 'Укажите улицу и дом',
    zip: /^\d{6}$/.test(values.zip) ? undefined : 'Индекс из шести цифр',
  };

  const stepFields: Array<Array<keyof RegistrationValues>> = [
    ['name', 'email', 'phone'],
    ['country', 'city', 'street', 'zip'],
    [],
  ];

  const stepIsValid = stepFields[step].every((field) => !errors[field]);
  const formIsValid = stepFields.flat().every((field) => !errors[field]);
  const showError = (field: keyof RegistrationValues) => (touched ? errors[field] : undefined);

  const goNext = () => {
    if (!stepIsValid) {
      setTouched(true);
      return;
    }
    setTouched(false);
    setStep((prev) => Math.min(prev + 1, STEPS.length - 1));
  };

  const goBack = () => {
    setTouched(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const submit = () => {
    if (!formIsValid) {
      setTouched(true);
      setStep(errors.name || errors.email || errors.phone ? 0 : 1);
      return;
    }
    onSubmit(values);
  };

  const summary: Array<{ label: string; value: string }> = [
    { label: 'Имя', value: values.name },
    { label: 'Почта', value: values.email },
    { label: 'Телефон', value: `+7${values.phone}` },
    {
      label: 'Страна',
      value: COUNTRIES.find((country) => country.value === values.country)?.label ?? '',
    },
    { label: 'Город', value: values.city },
    { label: 'Улица и дом', value: values.street },
    { label: 'Индекс', value: values.zip },
  ];

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        submit();
      }}
      style={{ display: 'flex', flexDirection: 'column', gap: 24, fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxStepper steps={STEPS} current={step} />

      <div
        aria-live="polite"
        style={{ display: 'flex', flexDirection: 'column', gap: 16, minHeight: 260 }}
      >
        {step === 0 && (
          <>
            <JxInputField
              label="Имя и фамилия"
              required
              autoComplete="name"
              placeholder="Анна Морозова"
              value={values.name}
              onChange={(event) => set('name', event.target.value)}
              errorText={showError('name')}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              autoComplete="email"
              placeholder="anna@example.com"
              helperText="На неё придёт письмо с подтверждением"
              value={values.email}
              onChange={(event) => set('email', event.target.value)}
              errorText={showError('email')}
            />
            <JxInputField
              label="Телефон"
              type="tel"
              required
              prefix="+7"
              autoComplete="tel"
              placeholder="9001234567"
              value={values.phone}
              onChange={(event) => set('phone', event.target.value.replace(/\D/g, ''))}
              errorText={showError('phone')}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxSelect
              label="Страна"
              placeholder="Выберите страну"
              options={COUNTRIES}
              value={values.country}
              onValueChange={(value) => set('country', value)}
            />
            {showError('country') && (
              <span style={{ color: 'var(--jx-danger)', fontSize: 13 }}>{errors.country}</span>
            )}
            <JxInputField
              label="Город"
              required
              autoComplete="address-level2"
              placeholder="Казань"
              value={values.city}
              onChange={(event) => set('city', event.target.value)}
              errorText={showError('city')}
            />
            <JxInputField
              label="Улица и дом"
              required
              autoComplete="street-address"
              placeholder="Баумана, 12, кв. 4"
              value={values.street}
              onChange={(event) => set('street', event.target.value)}
              errorText={showError('street')}
            />
            <JxInputField
              label="Почтовый индекс"
              required
              inputMode="numeric"
              autoComplete="postal-code"
              placeholder="420111"
              value={values.zip}
              onChange={(event) => set('zip', event.target.value.replace(/\D/g, '').slice(0, 6))}
              errorText={showError('zip')}
            />
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, 1fr) 2fr',
              gap: '12px 16px',
              margin: 0,
              padding: 16,
              background: 'var(--jx-surface-2)',
              border: '1px solid var(--jx-border)',
              borderRadius: 'var(--jx-r)',
            }}
          >
            {summary.map((row) => (
              <div key={row.label} style={{ display: 'contents' }}>
                <dt style={{ color: 'var(--jx-text-2)', fontSize: 14 }}>{row.label}</dt>
                <dd
                  style={{
                    margin: 0,
                    color: 'var(--jx-text)',
                    fontSize: 14,
                    overflowWrap: 'anywhere',
                  }}
                >
                  {row.value}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < STEPS.length - 1 ? (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

